from pathlib import Path

p = Path('lib/main.dart')
s = p.read_text(encoding='utf-8')

# 1) Real internet state: Firebase initialization is not the same thing as connectivity.
s = s.replace("import 'dart:convert';\nimport 'dart:math';", "import 'dart:convert';\nimport 'dart:io';\nimport 'dart:math';")
s = s.replace("  bool firebaseInitialized = false;\n  bool firebaseReady = false;", "  bool firebaseInitialized = false;\n  bool firebaseReady = false;\n  bool internetAvailable = false;\n  Timer? _internetMonitor;")
s = s.replace("    _disposed = true;\n    super.dispose();", "    _disposed = true;\n    _internetMonitor?.cancel();\n    super.dispose();")

old = '''  Future<void> connectFirebase() async {\n    if (!firebaseInitialized) {\n      firebaseReady = false;\n      safeNotify();\n      return;\n    }\n\n    try {\n      User? user = FirebaseAuth.instance.currentUser;\n      if (user == null) {\n        final credential = await FirebaseAuth.instance.signInAnonymously();\n        user = credential.user;\n      }\n\n      if (user == null) {\n        firebaseReady = false;\n        safeNotify();\n        return;\n      }\n\n      uid = user.uid;\n      firebaseReady = true;\n\n      // Load the cloud account state first. This prevents a reinstall/new local\n      // trial_start from overwriting the original trial start date.\n      await loadAccountState();\n\n      if (trialStart == null) {\n        trialStart = DateTime.now();\n        await _pref(() => prefs.setString(\n              'trial_start',\n              trialStart!.toIso8601String(),\n            ));\n        await userRef.doc(uid).set({\n          'trialStart': Timestamp.fromDate(trialStart!),\n          'deviceId': deviceId,\n          'activated': activated,\n        }, SetOptions(merge: true));\n      }\n\n      await pullCloud();\n\n      safeNotify();\n    } catch (e, stack) {\n      firebaseReady = false;\n      debugPrint('Firebase connection error: $e');\n      debugPrintStack(stackTrace: stack);\n      safeNotify();\n    }\n  }\n'''
new = '''  Future<bool> _probeInternet() async {\n    try {\n      final result = await InternetAddress.lookup('firebase.google.com')\n          .timeout(const Duration(seconds: 4));\n      return result.isNotEmpty && result.first.rawAddress.isNotEmpty;\n    } catch (_) {\n      return false;\n    }\n  }\n\n  Future<void> _refreshInternetState({bool syncWhenOnline = true}) async {\n    if (!firebaseInitialized) {\n      internetAvailable = false;\n      firebaseReady = false;\n      safeNotify();\n      return;\n    }\n\n    final online = await _probeInternet();\n    final changed = online != internetAvailable;\n    internetAvailable = online;\n    firebaseReady = online && uid.isNotEmpty;\n\n    if (online && uid.isNotEmpty && (changed || syncWhenOnline)) {\n      try {\n        await loadAccountState();\n        await pullCloud();\n      } catch (e) {\n        debugPrint('Online refresh error: $e');\n        internetAvailable = false;\n        firebaseReady = false;\n      }\n    }\n\n    safeNotify();\n  }\n\n  void _startInternetMonitor() {\n    _internetMonitor?.cancel();\n    _internetMonitor = Timer.periodic(const Duration(seconds: 12), (_) {\n      _refreshInternetState();\n    });\n  }\n\n  Future<void> connectFirebase() async {\n    if (!firebaseInitialized) {\n      firebaseReady = false;\n      internetAvailable = false;\n      safeNotify();\n      return;\n    }\n\n    try {\n      User? user = FirebaseAuth.instance.currentUser;\n      if (user == null) {\n        final credential = await FirebaseAuth.instance.signInAnonymously();\n        user = credential.user;\n      }\n\n      if (user == null) {\n        firebaseReady = false;\n        internetAvailable = false;\n        safeNotify();\n        return;\n      }\n\n      uid = user.uid;\n      _startInternetMonitor();\n      await _refreshInternetState();\n\n      if (!internetAvailable) {\n        debugPrint('Firebase initialized but internet is unavailable; staying offline.');\n        return;\n      }\n\n      if (trialStart == null) {\n        trialStart = DateTime.now();\n        await _pref(() => prefs.setString(\n              'trial_start',\n              trialStart!.toIso8601String(),\n            ));\n        await userRef.doc(uid).set({\n          'trialStart': Timestamp.fromDate(trialStart!),\n          'deviceId': deviceId,\n          'activated': activated,\n        }, SetOptions(merge: true));\n      }\n\n      await loadAccountState();\n      await pullCloud();\n      safeNotify();\n    } catch (e, stack) {\n      firebaseReady = false;\n      internetAvailable = false;\n      debugPrint('Firebase connection error: $e');\n      debugPrintStack(stackTrace: stack);\n      safeNotify();\n    }\n  }\n'''
if old not in s:
    raise SystemExit('connectFirebase block not found')
s = s.replace(old, new)

# Do not claim a cloud sync while offline.
s = s.replace("  Future<void> syncAll() async {\n    if (!firebaseReady || uid.isEmpty) return;", "  Future<void> syncAll() async {\n    if (!firebaseReady || !internetAvailable || uid.isEmpty) return;")

# 2) Activation codes are one-time, but no longer tied to the volatile local Device ID.
old = '''  Future<bool> activateCode(String code) async {\n    if (!firebaseReady || uid.isEmpty) return false;\n\n    final clean = _digits(code).trim();\n    if (clean.isEmpty) return false;\n\n    final ref = activationCodesRef.doc(clean);\n\n    try {\n      final success = await FirebaseFirestore.instance.runTransaction<bool>((transaction) async {\n        final snap = await transaction.get(ref);\n        if (!snap.exists) return false;\n\n        final data = snap.data();\n        if (data == null || data['used'] == true) return false;\n\n        final boundDevice = '${data['deviceId'] ?? ''}'.trim();\n        if (boundDevice.isNotEmpty && boundDevice != deviceId) return false;\n\n        transaction.update(ref, {\n          'used': true,\n          'usedAt': FieldValue.serverTimestamp(),\n          'usedDeviceId': deviceId,\n          'usedUid': uid,\n        });\n\n        return true;\n      });\n\n      if (!success) return false;\n\n      await userRef.doc(uid).set({\n        'activated': true,\n        'activatedAt': FieldValue.serverTimestamp(),\n        'deviceId': deviceId,\n      }, SetOptions(merge: true));\n\n      activated = true;\n      await saveLocal();\n      safeNotify();\n      return true;\n    } catch (e) {\n      debugPrint('Activation error: $e');\n      return false;\n    }\n  }\n\n  Future<String?> generateCode(String targetDevice) async {\n    if (!firebaseReady || !isAdmin || targetDevice.trim().isEmpty) return null;\n\n    final device = targetDevice.trim();\n\n    // Do not call get() on a missing activation-code document: the Firestore\n    // rules intentionally permit reads only for existing unused codes.\n    // Instead, attempt the create directly and retry on the extremely unlikely\n    // six-digit collision.\n    for (var attempt = 0; attempt < 50; attempt++) {\n      final code = (100000 + Random.secure().nextInt(900000)).toString();\n      final ref = activationCodesRef.doc(code);\n\n      try {\n        await ref.set({\n          'deviceId': device,\n          'used': false,\n          'createdAt': FieldValue.serverTimestamp(),\n          'createdByUid': uid,\n        });\n        return code;\n      } on FirebaseException catch (e) {\n        // A six-digit collision is harmless; generate another candidate.\n        if (e.code == 'permission-denied') continue;\n        debugPrint('Generate activation code error: ${e.code}: ${e.message}');\n        return null;\n      } catch (e) {\n        debugPrint('Generate activation code error: $e');\n        return null;\n      }\n    }\n\n    return null;\n  }\n'''
new = '''  Future<bool> activateCode(String code) async {\n    if (!firebaseReady || !internetAvailable || uid.isEmpty) return false;\n\n    final clean = _digits(code).trim();\n    if (clean.isEmpty) return false;\n\n    final ref = activationCodesRef.doc(clean);\n\n    try {\n      final success = await FirebaseFirestore.instance.runTransaction<bool>((transaction) async {\n        final snap = await transaction.get(ref);\n        if (!snap.exists) return false;\n\n        final data = snap.data();\n        if (data == null || data['used'] == true) return false;\n\n        final boundDevice = '${data['deviceId'] ?? ''}'.trim();\n        if (boundDevice.isEmpty) return false;\n\n        transaction.update(ref, {\n          'used': true,\n          'usedAt': FieldValue.serverTimestamp(),\n          // Keep the existing Firestore rule contract, but do NOT compare it\n          // with the volatile local device_id. The code is intentionally one-use.\n          'usedDeviceId': boundDevice,\n          'usedUid': uid,\n        });\n\n        return true;\n      });\n\n      if (!success) return false;\n\n      await userRef.doc(uid).set({\n        'activated': true,\n        'activatedAt': FieldValue.serverTimestamp(),\n        'activationCode': clean,\n      }, SetOptions(merge: true));\n\n      activated = true;\n      await saveLocal();\n      safeNotify();\n      return true;\n    } catch (e) {\n      debugPrint('Activation error: $e');\n      return false;\n    }\n  }\n\n  Future<String?> generateCode() async {\n    if (!firebaseReady || !internetAvailable || !isAdmin) return null;\n\n    // Keep the existing Firestore rules compatible by supplying a server-side\n    // binding token, not the client's volatile install-generated device ID.\n    final binding =\n        'ACT-${uid.substring(0, min(8, uid.length))}-${DateTime.now().millisecondsSinceEpoch}-${Random.secure().nextInt(1000000)}';\n\n    for (var attempt = 0; attempt < 50; attempt++) {\n      final code = (100000 + Random.secure().nextInt(900000)).toString();\n      final ref = activationCodesRef.doc(code);\n\n      try {\n        await ref.set({\n          'deviceId': binding,\n          'used': false,\n          'createdAt': FieldValue.serverTimestamp(),\n          'createdByUid': uid,\n          'version': 2,\n        });\n\n        // Force a server read so a queued/offline write cannot be reported as\n        // a successfully generated activation code.\n        final verify = await ref.get(const GetOptions(source: Source.server));\n        final data = verify.data();\n        if (verify.exists && data != null && data['used'] == false) {\n          return code;\n        }\n      } on FirebaseException catch (e) {\n        if (e.code == 'permission-denied' || e.code == 'already-exists') {\n          continue;\n        }\n        debugPrint('Generate activation code error: ${e.code}: ${e.message}');\n        return null;\n      } catch (e) {\n        debugPrint('Generate activation code error: $e');\n        return null;\n      }\n    }\n\n    return null;\n  }\n\n  Future<String?> deleteCustomer(Customer customer) async {\n    if (balance(customer.id) != 0) {\n      return 'لا يمكن حذف الزبون: عليه رصيد قدره ${money(balance(customer.id))}.';\n    }\n\n    if (!firebaseReady || !internetAvailable || uid.isEmpty) {\n      return 'لا يمكن الحذف الآن. يجب الاتصال بالإنترنت للتحقق من آخر رصيد محفوظ.';\n    }\n\n    try {\n      final serverTx = await transactionRef\n          .where('customerId', isEqualTo: customer.id)\n          .get(const GetOptions(source: Source.server));\n\n      var serverBalance = 0;\n      for (final doc in serverTx.docs) {\n        final data = doc.data();\n        final amount = data['amountCents'] is num\n            ? (data['amountCents'] as num).toInt()\n            : data['amount'] is num\n                ? ((data['amount'] as num).toDouble() * 100).round()\n                : 0;\n        serverBalance += data['type'] == 'payment' ? -amount : amount;\n      }\n\n      if (serverBalance != 0) {\n        return 'تم رفض الحذف: الرصيد السحابي الحالي ${money(serverBalance)}.';\n      }\n\n      final batch = FirebaseFirestore.instance.batch();\n      for (final doc in serverTx.docs) {\n        batch.delete(doc.reference);\n      }\n      batch.delete(customerRef.doc(customer.id));\n      await batch.commit();\n\n      customers.removeWhere((c) => c.id == customer.id);\n      transactions.removeWhere((t) => t.customerId == customer.id);\n      await saveLocal();\n      safeNotify();\n      return null;\n    } on FirebaseException catch (e) {\n      debugPrint('Delete customer error: ${e.code}: ${e.message}');\n      return 'تعذر الحذف من السحابة. لم يتم حذف الزبون.';\n    } catch (e) {\n      debugPrint('Delete customer error: $e');\n      return 'تعذر حذف الزبون. لم يتم حذف أي بيانات.';\n    }\n  }\n'''
if old not in s:
    raise SystemExit('activation block not found')
s = s.replace(old, new)

# 3) Customer deletion UI with mandatory zero-balance confirmation.
old = """    return Scaffold(\n      appBar: AppBar(title: Text(customer.name)),\n      body: ListView("""
new = """    return Scaffold(\n      appBar: AppBar(\n        title: Text(customer.name),\n        actions: [\n          IconButton(\n            tooltip: 'حذف الزبون',\n            icon: const Icon(Icons.delete_outline),\n            onPressed: () async {\n              final current = store.balance(customer.id);\n              if (current != 0) {\n                ScaffoldMessenger.of(context).showSnackBar(\n                  SnackBar(content: Text('لا يمكن الحذف. المتبقي: ${money(current)}')),\n                );\n                return;\n              }\n\n              final confirmed = await showDialog<bool>(\n                context: context,\n                builder: (dialogContext) => AlertDialog(\n                  title: const Text('حذف الزبون؟'),\n                  content: const Text(\n                    'سيتم حذف الزبون وسجل عملياته بعد التأكد من أن الرصيد يساوي صفرًا. لا يمكن التراجع عن العملية.',\n                  ),\n                  actions: [\n                    TextButton(\n                      onPressed: () => Navigator.pop(dialogContext, false),\n                      child: const Text('إلغاء'),\n                    ),\n                    FilledButton(\n                      onPressed: () => Navigator.pop(dialogContext, true),\n                      child: const Text('حذف نهائي'),\n                    ),\n                  ],\n                ),\n              ) ?? false;\n\n              if (!confirmed || !context.mounted) return;\n\n              final error = await store.deleteCustomer(customer);\n              if (!context.mounted) return;\n              if (error != null) {\n                ScaffoldMessenger.of(context).showSnackBar(\n                  SnackBar(content: Text(error)),\n                );\n              } else {\n                Navigator.pop(context);\n              }\n            },\n          ),\n        ],\n      ),\n      body: ListView("""
if old not in s:
    raise SystemExit('customer appbar not found')
s = s.replace(old, new, 1)

# 4) Admin panel no longer asks for the volatile Device ID.
s = s.replace("  final device = TextEditingController();\n", "")
s = s.replace("    device.dispose();\n", "")
s = s.replace("    final target = device.text.trim();\n    if (target.isEmpty) {\n      ScaffoldMessenger.of(context).showSnackBar(\n        const SnackBar(content: Text('أدخل Device ID للعميل')),\n      );\n      return;\n    }\n\n", "")
s = s.replace("    final generated = await widget.store.generateCode(target);", "    final generated = await widget.store.generateCode();")
old = '''          TextField(\n            controller: device,\n            decoration: const InputDecoration(\n              labelText: 'Device ID للعميل',\n              hintText: 'مثال: DP-...',\n            ),\n          ),\n          const SizedBox(height: 12),\n'''
s = s.replace(old, "          const Card(\n            child: ListTile(\n              leading: Icon(Icons.lock_reset_rounded),\n              title: Text('رمز مستقل عن الهاتف'),\n              subtitle: Text('الرمز صالح لمرة واحدة ولا يرتبط بمعرّف تثبيت متغير.'),\n            ),\n          ),\n          const SizedBox(height: 12),\n")
s = s.replace("ok ? 'تم التفعيل الدائم بنجاح' : 'الكود غير صحيح أو مستخدم أو مخصص لجهاز آخر'", "ok ? 'تم التفعيل الدائم بنجاح' : 'الكود غير صحيح أو مستخدم أو لم يمكن التحقق من الخادم'")
s = s.replace("'طلب تفعيل DainPay - رقم الجهاز: ${store.deviceId}'", "'طلب تفعيل DainPay'")

# 5) Show actual internet state in Settings/Admin labels.
s = s.replace("subtitle: Text(store.firebaseReady ? 'متصل' : 'غير متصل'),", "subtitle: Text(store.internetAvailable ? 'متصل بالإنترنت والمزامنة متاحة' : 'غير متصل بالإنترنت — العمل محلي'),")
s = s.replace("store.firebaseReady ? Icons.cloud_done : Icons.cloud_off", "store.internetAvailable ? Icons.cloud_done : Icons.cloud_off")
s = s.replace("store.firebaseReady ? mint : burgundy", "store.internetAvailable ? mint : burgundy")
s = s.replace("subtitle: Text(store.firebaseReady ? 'متصل بـ Firebase' : 'غير متصل بـ Firebase'),", "subtitle: Text(store.internetAvailable ? 'متصل بالإنترنت — Firebase متاح' : 'غير متصل بالإنترنت'),")

p.write_text(s, encoding='utf-8')
